def solve(jobs):
    jobs = sorted(jobs, key=lambda job: job[1])
    ends = [job[1] for job in jobs]
    dp = [0] * (len(jobs) + 1)

    for i, (start, end, weight) in enumerate(jobs, 1):
        lo, hi = 0, i - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if ends[mid] <= start:
                lo = mid + 1
            else:
                hi = mid
        compatible = lo if lo < i - 1 and ends[lo] <= start else (lo if ends[lo] <= start else lo - 1)
        dp[i] = max(dp[i - 1], dp[compatible + 1] + weight)

    return dp[-1]
